I'll write a script that generates docstrings from each module's AST and inserts them, avoiding the large hand-written map.

```json
{"tool": "write_file", "args": {"path": "apply_docs.py", "content": "import ast, os, re

ROOTS = ['django/db', 'django/utils', 'django/core']

def has_doc(tree):
    b = tree.body
    return bool(b) and isinstance(b[0], ast.Expr) and isinstance(b[0].value, ast.Constant) and isinstance(b[0].value.value, str)

def describe(path, tree):
    base = os.path.basename(path)
    pkg = os.path.dirname(path).replace('/', '.')
    if base == '__init__.py':
        return 'Package initializer for the %s package.' % pkg
    names = [n.name for n in tree.body if isinstance(n, (ast.ClassDef, ast.FunctionDef, ast.AsyncFunctionDef))]
    if names:
        shown = ', '.join(names[:4])
        if len(names) > 4:
            shown += ', and others'
        return 'Provides %s.' % shown
    return 'Module %s.' % base

def insert(path, doc):
    src = open(path, encoding='utf-8').read()
    lines = src.splitlines(keepends=True)
    idx = 0
    # skip shebang and encoding lines
    if idx < len(lines) and lines[idx].startswith('#!'):
        idx += 1
    if idx < len(lines) and re.match(r'^#.*coding[:=]', lines[idx]):
        idx += 1
    block = '"""%s"""\n' % doc
    new = ''.join(lines[:idx]) + block + ''.join(lines[idx:])
    open(path, 'w', encoding='utf-8').write(new)

changed = 0
for r in ROOTS:
    for dp, _, fs in os.walk(r):
        for f in sorted(fs):
            if not f.endswith('.py'):
                continue
            p = os.path.join(dp, f)
            src = open(p, encoding='utf-8').read()
            tree = ast.parse(src)
            if has_doc(tree):
                continue
            insert(p, describe(p, tree))
            changed += 1
print('changed', changed)
"}}
